source.patch:
From 6f43e71f4cbddf96d47648f36161a9815389b50a Mon Sep 17 00:00:00 2001
From: Reini Urban <reini.urban@gmail.com>
Date: Tue, 23 Jan 2024 13:24:26 +0100
Subject: [PATCH] indxf: reject invalid number pairs

0\nSECTION ok,
0SECTION not ok.
---
 src/in_dxf.c | 38 ++++++++++++++++++++++++++++++++++----
 1 file changed, 34 insertions(+), 4 deletions(-)

diff --git a/src/in_dxf.c b/src/in_dxf.c
index ee2319f..50027e6 100644
--- a/src/in_dxf.c
+++ b/src/in_dxf.c
@@ -290,7 +290,7 @@ dxf_skip_ws (Bit_Chain *dat)
     if (errno == ERANGE)                                                      \
       return (rettype)num;                                                    \
     if (dat->byte + 1 >= dat->size)                                           \
-    return (rettype)num
+      return (rettype)num

 static BITCODE_RC
 dxf_read_rc (Bit_Chain *dat)
@@ -310,9 +310,18 @@ dxf_read_rc (Bit_Chain *dat)
         dat->byte++;
       if (dat->chain[dat->byte] == '\n')
         dat->byte++;
+      else
+        {
+          LOG_ERROR ("%s: \\n missing after %ld (at %" PRIuSIZE ")",
+                     __FUNCTION__, num, dat->byte);
+          dat->byte = dat->size;
+        }
       if (num > UINT8_MAX)
-        LOG_ERROR ("%s: RC overflow %ld (at %" PRIuSIZE ")", __FUNCTION__, num,
-                   dat->byte);
+        {
+          LOG_ERROR ("%s: RC overflow %ld (at %" PRIuSIZE ")", __FUNCTION__, num,
+                     dat->byte);
+          dat->byte = dat->size;
+        }
       return (BITCODE_RC)num;
     }
 }
@@ -334,9 +343,18 @@ dxf_read_rs (Bit_Chain *dat)
         dat->byte++;
       if (dat->chain[dat->byte] == '\n')
         dat->byte++;
+      else
+        {
+          LOG_ERROR ("%s: \\n missing after %ld (at %" PRIuSIZE ")",
+                     __FUNCTION__, num, dat->byte);
+          dat->byte = dat->size;
+        }
       if (num > UINT16_MAX)
-        LOG_ERROR ("%s: RS overflow %ld (at %" PRIuSIZE ")", __FUNCTION__, num,
+        {
+          LOG_ERROR ("%s: RS overflow %ld (at %" PRIuSIZE ")", __FUNCTION__, num,
                    dat->byte);
+          dat->byte = dat->size;
+        }
       return (BITCODE_RS)num;
     }
 }
@@ -359,6 +377,12 @@ dxf_read_rl (Bit_Chain *dat)
         dat->byte++;
       if (dat->chain[dat->byte] == '\n')
         dat->byte++;
+      else
+        {
+          LOG_ERROR ("%s: \\n missing after %ld (at %" PRIuSIZE ")",
+                     __FUNCTION__, num, dat->byte);
+          dat->byte = dat->size;
+        }
       /*
       if (num > (long)0xffffffff)
         LOG_ERROR ("%s: RL overflow %ld (at %" PRIuSIZE ")", __FUNCTION__, num,
@@ -386,6 +410,12 @@ dxf_read_rll (Bit_Chain *dat)
         dat->byte++;
       if (dat->chain[dat->byte] == '\n')
         dat->byte++;
+      else
+        {
+          LOG_ERROR ("%s: \\n missing after %ld (at %" PRIuSIZE ")",
+                     __FUNCTION__, (long)num, dat->byte);
+          dat->byte = dat->size;
+        }
       return num;
     }
 }
